// Collapse the engine's verdict into one boolean.
//
// Why this is a Code node rather than a condition on the IF node directly:
// the decision is "skip the agent when the engine already produced the
// customer-visible answer, or when it asked for silence". Expressed as a
// nested filter group that is unreadable and easy to get subtly wrong;
// expressed here it is one commented line, and the IF node downstream only has
// to compare a single boolean.
const gate = $input.item.json ?? {};

const action = String(gate.action || "continue");
const muted = gate.muteAi === true;
const continuesWithAi = gate.continueWithAi === true;

const messages = Array.isArray(gate.messages) ? gate.messages : [];
const gateText = messages
  .map((message) => (message && typeof message.text === "string" ? message.text : ""))
  .filter(Boolean)
  .join("\n\n");

// `muteAi` covers `pause_ai` and `handoff_to_human` — a human owns the thread,
// so the agent must not speak. `action === "reply"` is the canned answer.
//
// `continueWithAi` is the deliberate exception: the merchant asked for
// "send this, then let the AI carry on". The Format Response node prepends
// `gateText` to the agent's answer, so here the agent has to run.
const skipAi = muted || (action === "reply" && !continuesWithAi);

return [{ json: { ...gate, skipAi, gateText } }];

// ─────────────────────────────────────────────────────────────────────────────
// Quota Blocked Reply
// The platform refused the AI call (credits exhausted, or the workspace was
// suspended). This node is where the turn ends instead of at `Return to Platform`.
//
// It deliberately does NOT chain into Save Chat History or Billing API: no model
// ran, so there is nothing to record and nothing to charge. `billingOk: true`
// carries the same meaning it does on `Gate Return` — "nothing further is owed
// for this turn" — which is what stops the caller from deducting anything.
// ─────────────────────────────────────────────────────────────────────────────
const verdict = $input.item.json ?? {};
// The customer-facing copy rides on the Gate's own answer now (`quota.replyText`)
// rather than on a separate `Quota Check` node — TASK-11 folded that call into
// `Automation Gate`, because it was a second round trip to the same platform.
// The `verdict.replyText` fallback covers an older Gate node during a version skew.
const copy = verdict.quota?.replyText ?? verdict.replyText ?? {};

// Which of the two copies to use. The AI Agent normally mirrors the customer's
// own language, but on these paths no model runs — so the only signal left is
// the script of the message the customer sent. Banglish (Bengali typed in Latin
// letters) reads as English here, which is the safe way to be wrong: the English
// copy is still a sentence a Bengali speaker understands.
const BENGALI = /[\u0980-\u09FF]/;
const userMessage = String($('When Called by Platform').item.json.userMessage || '');
const lang = BENGALI.test(userMessage) ? 'bn' : 'en';

// Reached only if the platform answered without copy — i.e. a version skew.
// Kept in English and kept short: it is the last resort, not the normal path.
const FALLBACK = "Sorry, I can't reply right now. Please message again in a little while.";
const replyText = copy[lang] || copy.en || FALLBACK;

return [{ json: {
  replyText,
  galleryImages: [],
  isOrderCreated: false,
  promptTokens: 0,
  completionTokens: 0,
  totalTokens: 0,
  costUsd: 0,
  costBdt: 0,
  creditsSpent: 0,
  billingOk: true,
  tokensAreExact: true
} }];

// ─────────────────────────────────────────────────────────────────────────────
// AI Failed Reply
// The AI Agent itself threw — the reply could not be generated at all.
//
// Why this node exists at all: n8n's OpenRouter Chat Model sub-node cannot send
// OpenRouter's `models: [...]` fallback list (it has no such field — see the
// `Quota Guard` sticky note), so a dead model id, a provider outage or n8n's own
// OpenRouter balance running dry have no second model to fall back to. Without
// this branch those failures ended as *silence*: the workflow errored before
// Format Response, the caller read an empty replyText, and on Facebook that
// became a Graph API call with an empty text — a 400 the customer never sees.
//
// This node cannot make the answer happen; it makes the *silence* not happen.
// ─────────────────────────────────────────────────────────────────────────────
// The copy comes from the platform (the same JSON the blocked path uses), so the
// customer-facing wording lives in one place. `try` because `$(...)` throws on a
// node that did not run — the same guard Format Response uses for the Gate.
//
// ⚡ Asked of `Gate Decision`, not of a `Quota Check` node: TASK-11 folded the
//    quota pre-flight into `Automation Gate` and deleted that node, and naming an
//    unexecuted node throws. Put `Quota Check` back and this must change with it.
let copy = {};
try {
  copy = $('Gate Decision').item.json.quota?.replyText ?? {};
} catch (err) {
  copy = {};
}

// Which of the two copies to use. The AI Agent normally mirrors the customer's
// own language, but on these paths no model runs — so the only signal left is
// the script of the message the customer sent. Banglish (Bengali typed in Latin
// letters) reads as English here, which is the safe way to be wrong: the English
// copy is still a sentence a Bengali speaker understands.
const BENGALI = /[\u0980-\u09FF]/;
const userMessage = String($('When Called by Platform').item.json.userMessage || '');
const lang = BENGALI.test(userMessage) ? 'bn' : 'en';

const FALLBACK = "Sorry, I can't reply right now. Please message again in a little while.";
const replyText = copy[lang] || copy.en || FALLBACK;

return [{ json: {
  replyText,
  galleryImages: [],
  isOrderCreated: false,
  promptTokens: 0,
  completionTokens: 0,
  totalTokens: 0,
  costUsd: 0,
  costBdt: 0,
  creditsSpent: 0,
  billingOk: true,
  tokensAreExact: true
} }];
